import{_ as o,a as e,b as r}from"./chunks/rtk_holybro_h-rtk-m8p_spec.1RfFdMI0.js";import{_ as s}from"./chunks/rtk_holybro_h-rtk_mount_3.DwLha2Oo.js";import{_ as t,o as i,c as l,al as p}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"Holybro H-RTK M8P GNSS (Знято з виробництва)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/gps_compass/rtk_gps_holybro_h-rtk-m8p.md","filePath":"uk/gps_compass/rtk_gps_holybro_h-rtk-m8p.md"}'),n={name:"uk/gps_compass/rtk_gps_holybro_h-rtk-m8p.md"};function h(c,a,m,_,d,b){return i(),l("div",null,[...a[0]||(a[0]=[p('<h1 id="holybro-h-rtk-m8p-gnss-знято-з-виробництва" tabindex="-1">Holybro H-RTK M8P GNSS (Знято з виробництва) <a class="header-anchor" href="#holybro-h-rtk-m8p-gnss-знято-з-виробництва" aria-label="Permalink to &quot;Holybro H-RTK M8P GNSS (Знято з виробництва)&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This GNSS has been discontinued, and is no longer commercially available. Replaced by <a href="./../gps_compass/rtk_gps_holybro_h-rtk-f9p">Holybro H-RTK F9P GNSS</a>.</p></div><p>The <em>Holybro H-RTK M8P GNSS</em> is an <a href="./../gps_compass/rtk_gps">RTK GNSS module</a> series for the mass market. This family is similar to the <a href="./../gps_compass/rtk_gps_holybro_h-rtk-f9p">H-RTK M9P</a> series but uses the smaller, lighter, and less expensive M8P u-blox RTK GNSS module (which still provides far superior position resolution than previous generations_.</p><p>Є три моделі Holybro H-RTK M8P на вибір, кожна з різним дизайном антени, щоб задовольнити різні потреби. Refer to the <a href="#specification-and-model-comparison">Specification and Model Comparison section</a> for more details.</p><p>Використання RTK дозволяє PX4 отримати своє положення з точністю до сантиметрів, що набагато точніше, ніж може забезпечити звичайний GPS.</p><p><img src="'+o+'" alt="h-rtk_rover"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><ul><li>Припинено.</li></ul><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>RTK setup and use on PX4 via <em>QGroundControl</em> is largely plug and play (see <a href="./../gps_compass/rtk_gps">RTK GPS</a> for more information).</p><h2 id="підключення-та-з-єднання" tabindex="-1">Підключення та з&#39;єднання <a class="header-anchor" href="#підключення-та-з-єднання" aria-label="Permalink to &quot;Підключення та з&#39;єднання&quot;">​</a></h2><p>All H-RTK GNSS models come with a GH 10-pin connector/cable that is compatible with <a href="./../flight_controller/pixhawk4">Pixhawk 4</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The cables/connectors may need to be modified in order to connect to other flight controller boards (see <a href="#pin_map">pin map</a>below).</p></div><h2 id="pin_map" tabindex="-1">Pin Map <a class="header-anchor" href="#pin_map" aria-label="Permalink to &quot;Pin Map {#pin_map}&quot;">​</a></h2><p><img src="'+e+'" alt="h-rtk_rover_pinmap"></p><h2 id="специфікація-та-порівняння-моделеи" tabindex="-1">Специфікація та порівняння моделей <a class="header-anchor" href="#специфікація-та-порівняння-моделеи" aria-label="Permalink to &quot;Специфікація та порівняння моделей&quot;">​</a></h2><p><img src="'+r+'" alt="h-rtk_spec"></p><h2 id="аксесуари-до-gps" tabindex="-1">Аксесуари до GPS <a class="header-anchor" href="#аксесуари-до-gps" aria-label="Permalink to &quot;Аксесуари до GPS&quot;">​</a></h2><p><a href="https://holybro.com/collections/gps-accessories" target="_blank" rel="noreferrer">GPS Accessories (Holybro Website)</a></p><p><img src="'+s+'" alt="h-rtk"></p>',20)])])}const P=t(n,[["render",h]]);export{g as __pageData,P as default};
